import type { RuleSection } from './rulebookTypes';

type Draft = {
  id: string;
  title: string;
  discipline: string;
  level: number;
  pages: string;
  summary: string;
  details: string[];
  cost: string;
  pool?: string;
  duration: string;
  extraTags?: string[];
};

const power = (d: Draft): RuleSection['entries'][number] => ({
  id: d.id,
  title: d.title,
  summary: d.summary,
  paragraphs: d.details,
  bullets: [
    `Уровень: ${d.level}`,
    `Расход: ${d.cost}`,
    ...(d.pool ? [`Пул: ${d.pool}`] : []),
    `Длительность: ${d.duration}`,
  ],
  tags: ['дисциплина', `уровень-${d.level}`, d.discipline, ...(d.extraTags ?? [])],
  source: { book: 'core', pages: d.pages },
});

const common = (id: string, title: string, pages: string, details: string[], discipline?: string): RuleSection['entries'][number] => ({
  id,
  title,
  summary: details[0],
  paragraphs: details.slice(1),
  tags: ['дисциплина', 'уровень-1', 'уровень-2', 'уровень-3', 'уровень-4', 'уровень-5', 'уровень-общий', ...(discipline ? [discipline] : []), 'общие правила'],
  source: { book: 'core', pages },
});

